// Everything tunable lives here so nothing downstream hardcodes it.
//
// The category list is the single most important input. G2's API, on a
// buyer-scoped token, returns only the TOP products of a category. In a
// broad category ("CRM", "Sales Engagement") those are Salesforce and
// Apollo -- giants who need nothing from us. In a narrow category the top
// products ARE the whole category, and that is where every usable prospect
// has come from. Measured yield: ~1.6 per narrow category, 0 per broad one.
//
// So: add narrow categories. Resist adding broad ones.
return [{ json: {
  categories: [
    'ai-sales-roleplay-tools',
    'ai-proposal-generator-tools',
    'event-lead-capture',
    'ai-interview-agent',
    'ai-documentation-generators',
    'site-search-software',
    'ai-sre-tools',
    'website-privacy-auditing-tools',
    'ai-agent-observability',
    'semantic-layer-tools',
    'virtual-recording-studio',
    'low-code-mobile-app-builder'
  ],
  minReviews: 10,
  maxReviews: 250,
  campaignId: 'df17f3eb-368d-415f-99ab-b6a7325dad3c',
  // Competitors, and companies selling the outcome we sell. Both turn up in
  // exactly the categories worth sweeping.
  excludeDomains: [
    'linkfinderai.com','clay.com','warmly.ai','6sense.com','apollo.io',
    'zoominfo.com','lusha.com','cognism.com','hunter.io','snov.io',
    'rocketreach.co','seamless.ai','uplead.com','findymail.com',
    'dropcontact.com','kaspr.io','surfe.com','prospeo.io','anymailfinder.com',
    'tryprofound.com','peec.ai','otterly.ai','athenahq.ai','scrunchai.com',
    'goodie.ai','brandlight.ai'
  ]
} }];

// Refuse to spend a credit we cannot use.
//
// This node exists because of a real afternoon: the workspace sat 6,089
// leads over its cap, so every upload would have 403'd -- but only AFTER
// LinkFinder had been paid for each enrichment. Credits gone, nothing to
// show for it.
const cfg = $('Config').first().json;
const plan = $input.first().json;
const sub = plan?.subscriptions?.outreach || plan || {};
const limit = sub.total_lead_limit;
const used  = sub.current_lead_count;

if (limit == null || used == null) {
  return [{ json: { ...cfg, room: null, note: 'lead limit unreadable; continuing' } }];
}

const room = limit - used;
if (room <= 0) {
  throw new Error(
    `Instantly has no room: ${used}/${limit}, ${-room} over the cap. ` +
    `Free space before running this, or you will pay to enrich leads that ` +
    `cannot be uploaded.`
  );
}
return [{ json: { ...cfg, room } }];

// Keep only what is worth paying to enrich.
//
// The review band is the qualifier:
//   below min  a stub listing, often a solo project with no budget
//   in band    listed, real, small enough that nobody built them a content
//              engine yet  <- the prospect
//   above max  category leader with an SEO team; the pitch insults them
const cfg = $('Stop if no room').first().json;
const out = [];

for (const item of $input.all()) {
  const slug = item.json.slug || '';
  const body = item.json.body ?? item.json;
  const categoryName = body?.data?.attributes?.name || slug;
  const included = body?.included || [];

  const products = included
    .filter(i => i.type === 'products' && i.attributes?.domain)
    .map(i => ({
      domain: String(i.attributes.domain).trim().toLowerCase(),
      company: i.attributes.name || '',
      reviewCount: i.attributes.review_count || 0
    }));

  if (!products.length) continue;

  // If even the smallest product G2 will show us is above the band, this
  // category has no reachable tail -- every row we could get belongs to a
  // company with a content team. Skip rather than pitch them.
  const smallest = Math.min(...products.map(p => p.reviewCount));
  if (smallest > cfg.maxReviews) continue;

  for (const p of products) {
    if (cfg.excludeDomains.includes(p.domain)) continue;
    if (p.reviewCount < cfg.minReviews || p.reviewCount > cfg.maxReviews) continue;
    out.push({ json: { ...p, category: categoryName, campaignId: cfg.campaignId } });
  }
}

// Never enrich more than we can upload.
const room = cfg.room;
const capped = (room && room > 0) ? out.slice(0, room) : out;
return capped;

// The failure that HTTP status codes do not describe.
//
// This endpoint answers 200 / "success" even when its upstream is down,
// putting a status message where a person should be:
//   {"personId": null, "name": "We are on maintenance. Check back in 48hrs"}
//
// Measured across ~20 live calls it comes back for roughly HALF of them,
// interleaved with perfectly good answers for similar domains seconds
// apart. So one sentinel means try again, not "the provider is down".
//
// ORDER MATTERS HERE. Look for a real person FIRST, and only ask why we
// failed when we actually failed. The actor also injects a chatty banner
// row ("We improve the Actor everyday...") alongside genuine results, so
// checking for sentinels first would throw away a good lead and pay to
// look it up again. Real data present always wins.
//
// When there is no person, two rows look similar and mean opposite things:
//   "No Leads found. Tweak your filters"  -> a real, empty answer. Accept it.
//   "We are on maintenance..."            -> the provider. Retry it.
// Treating the first as an outage would triple the cost of every dead
// domain; treating the second as an answer writes off a good company.
const OUTAGE = ['maintenance','check back in','we improve the actor','contact us if you are having'];

const prospect = $('One prospect at a time').first().json;
const body = $input.first().json;
const payload = body?.body ?? body;
let rows = payload?.result ?? payload?.employees ?? payload;
while (rows && !Array.isArray(rows) && rows.result) rows = rows.result;
if (!Array.isArray(rows)) rows = [];

const person = rows.find(r => r && (r.personId || r.person_id) &&
  r.email && String(r.email).includes('@') && r.name);

if (person) {
  const parts = String(person.name).trim().split(/\s+/);
  return [{ json: { ...prospect, status: 'ok',
    email: person.email.trim(),
    firstName: parts[0],
    lastName: parts.slice(1).join(' '),
    title: person.jobTitle || person.job_title || '' } }];
}

const sentinel = rows.find(r => r && !r.personId && !r.person_id &&
  OUTAGE.some(m => String(r.name || '').toLowerCase().includes(m)));

if (sentinel) {
  return [{ json: { ...prospect, status: 'provider_down', reason: sentinel.name } }];
}

return [{ json: { ...prospect, status: 'no_person' } }];
